using System.Collections.ObjectModel;
using System.Globalization;
using System.Windows;
using System.Windows.Controls;
using System.Windows.Media;
using KhanBabaPos.Wpf.Services;
namespace KhanBabaPos.Wpf;
public sealed class PurchasesWindow:Window
{
 readonly InventoryService inventory=new();readonly PurchaseService service=new();readonly ObservableCollection<InventoryProduct> products=[];readonly ObservableCollection<PurchaseRow> purchases=[];
 readonly TextBox search=new(){Padding=new Thickness(8),MinWidth=250};readonly DataGrid productGrid=new(){AutoGenerateColumns=false,IsReadOnly=true,CanUserAddRows=false,EnableRowVirtualization=true,RowHeight=34};readonly DataGrid purchaseGrid=new(){AutoGenerateColumns=false,IsReadOnly=true,CanUserAddRows=false,EnableRowVirtualization=true,RowHeight=34};
 readonly TextBox quantity=new(){Text="1",Padding=new Thickness(7)};readonly TextBox cost=new(){Padding=new Thickness(7)};readonly TextBox salePrice=new(){Padding=new Thickness(7)};readonly CheckBox updateSale=new(){Content="Update retail sale price too"};readonly TextBlock status=new(){Foreground=Brushes.DimGray};
 InventoryProduct? selected;
 public PurchasesWindow(){Title="Purchases | Khan Baba POS";Width=1280;Height=780;MinWidth=980;MinHeight=620;WindowStartupLocation=WindowStartupLocation.CenterOwner;Background=Brushes.WhiteSmoke;productGrid.ItemsSource=products;purchaseGrid.ItemsSource=purchases;Configure();Content=Layout();search.TextChanged+=async(_,_)=>await LoadProductsAsync();productGrid.SelectionChanged+=(_,_)=>SelectProduct();Loaded+=async(_,_)=>{await LoadProductsAsync();await LoadPurchasesAsync();};}
 void Configure(){productGrid.Columns.Add(new DataGridTextColumn{Header="Product",Binding=new System.Windows.Data.Binding("Name"),Width=new DataGridLength(1,DataGridLengthUnitType.Star)});productGrid.Columns.Add(new DataGridTextColumn{Header="Barcode",Binding=new System.Windows.Data.Binding("Barcode"),Width=120});productGrid.Columns.Add(new DataGridTextColumn{Header="Stock",Binding=new System.Windows.Data.Binding("Quantity"),Width=70});productGrid.Columns.Add(new DataGridTextColumn{Header="Unit",Binding=new System.Windows.Data.Binding("StockUnit"),Width=60});
 purchaseGrid.Columns.Add(new DataGridTextColumn{Header="Date",Binding=new System.Windows.Data.Binding("Date"),Width=155});purchaseGrid.Columns.Add(new DataGridTextColumn{Header="Product",Binding=new System.Windows.Data.Binding("ProductName"),Width=new DataGridLength(1,DataGridLengthUnitType.Star)});purchaseGrid.Columns.Add(new DataGridTextColumn{Header="Qty",Binding=new System.Windows.Data.Binding("Quantity"),Width=60});purchaseGrid.Columns.Add(new DataGridTextColumn{Header="Unit Cost",Binding=new System.Windows.Data.Binding("UnitCost"){StringFormat="N2"},Width=95});purchaseGrid.Columns.Add(new DataGridTextColumn{Header="Total",Binding=new System.Windows.Data.Binding("TotalCost"){StringFormat="N2"},Width=100});
 foreach(var g in new[]{productGrid,purchaseGrid}){g.SetValue(VirtualizingPanel.IsVirtualizingProperty,true);g.SetValue(VirtualizingPanel.VirtualizationModeProperty,VirtualizationMode.Recycling);ScrollViewer.SetCanContentScroll(g,true);}}
 UIElement Layout(){var root=new DockPanel{Margin=new Thickness(18)};var header=new DockPanel{LastChildFill=false,Margin=new Thickness(0,0,0,14)};var title=new StackPanel();title.Children.Add(new TextBlock{Text="Purchases / Stock Entry",FontSize=25,FontWeight=FontWeights.Bold,Foreground=Brushes.DarkSlateGray});title.Children.Add(new TextBlock{Text="Search inventory products and record stock purchases.",Foreground=Brushes.DimGray,Margin=new Thickness(0,4,0,0)});header.Children.Add(title);var refresh=Btn("Refresh");refresh.Click+=async(_,_)=>{await LoadProductsAsync();await LoadPurchasesAsync();};DockPanel.SetDock(refresh,Dock.Right);header.Children.Add(refresh);DockPanel.SetDock(header,Dock.Top);root.Children.Add(header);
 var split=new Grid();split.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(420),MinWidth=350});split.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(8)});split.ColumnDefinitions.Add(new ColumnDefinition{Width=new GridLength(1,GridUnitType.Star),MinWidth=430});
 var left=new DockPanel{Margin=new Thickness(0,0,8,0)};var form=new StackPanel();form.Children.Add(new TextBlock{Text="Search product name or barcode",FontWeight=FontWeights.SemiBold});form.Children.Add(search);form.Children.Add(new TextBlock{Text="Available products",Margin=new Thickness(0,10,0,6),FontWeight=FontWeights.SemiBold});var listBorder=new Border{BorderBrush=new SolidColorBrush(Color.FromRgb(220,229,224)),BorderThickness=new Thickness(1),Background=Brushes.White,Height=220,Child=productGrid};form.Children.Add(listBorder);form.Children.Add(new TextBlock{Text="Purchase quantity",Margin=new Thickness(0,12,0,4)});form.Children.Add(quantity);form.Children.Add(new TextBlock{Text="Unit purchase cost (Rs.)",Margin=new Thickness(0,8,0,4)});form.Children.Add(cost);form.Children.Add(updateSale);form.Children.Add(new TextBlock{Text="New retail sale price (Rs.)",Margin=new Thickness(0,4,0,4)});form.Children.Add(salePrice);var save=Btn("Save Purchase / Update Stock");save.Click+=async(_,_)=>await SaveAsync();form.Children.Add(save);left.Children.Add(form);Grid.SetColumn(left,0);split.Children.Add(left);
 var splitter=new GridSplitter{Width=8,ResizeDirection=GridResizeDirection.Columns,HorizontalAlignment=HorizontalAlignment.Stretch,VerticalAlignment=VerticalAlignment.Stretch,Background=new SolidColorBrush(Color.FromRgb(220,229,224))};Grid.SetColumn(splitter,1);split.Children.Add(splitter);
 var right=new DockPanel{Margin=new Thickness(8,0,0,0)};var sub=new TextBlock{Text="Purchase History",FontSize=18,FontWeight=FontWeights.SemiBold,Margin=new Thickness(0,0,0,8)};DockPanel.SetDock(sub,Dock.Top);right.Children.Add(sub);right.Children.Add(purchaseGrid);DockPanel.SetDock(status,Dock.Bottom);status.Margin=new Thickness(0,8,0,0);right.Children.Add(status);Grid.SetColumn(right,2);split.Children.Add(right);root.Children.Add(split);return root;}
 static Button Btn(string s)=>new(){Content=s,Padding=new Thickness(12,8,12,8),Margin=new Thickness(0,8,0,0)};
 async Task LoadProductsAsync(){try{var rows=await inventory.GetProductsAsync(search.Text);products.Clear();foreach(var p in rows)products.Add(p);if(selected!=null){selected=products.FirstOrDefault(x=>x.Id==selected.Id);}if(selected==null&&products.Count>0)productGrid.SelectedIndex=0;else if(selected!=null)productGrid.SelectedItem=selected;status.Text=$"{products.Count} matching product(s)";}catch(Exception e){status.Text="Product search failed: "+e.Message;}}
 void SelectProduct(){if(productGrid.SelectedItem is not InventoryProduct p)return;selected=p;cost.Text=p.PurchasePrice.ToString(CultureInfo.InvariantCulture);salePrice.Text=p.SalePrice.ToString(CultureInfo.InvariantCulture);}
 async Task LoadPurchasesAsync(){try{var rows=await service.GetAllAsync();purchases.Clear();foreach(var p in rows)purchases.Add(p);}catch(Exception e){status.Text="Purchase history load failed: "+e.Message;}}
 async Task SaveAsync(){if(selected==null){status.Text="Select a product first.";return;}if(!int.TryParse(quantity.Text,NumberStyles.Integer,CultureInfo.InvariantCulture,out var q)||q<=0||!double.TryParse(cost.Text,NumberStyles.Number,CultureInfo.InvariantCulture,out var c)||!double.IsFinite(c)||c<0){status.Text="Enter valid quantity and purchase cost.";return;}double? retail=null;if(updateSale.IsChecked==true){if(!double.TryParse(salePrice.Text,NumberStyles.Number,CultureInfo.InvariantCulture,out var p)||!double.IsFinite(p)||p<0){status.Text="Enter a valid new retail sale price.";return;}retail=p;}try{var id=selected.Id;await service.RecordAsync(id,q,c,retail);quantity.Text="1";updateSale.IsChecked=false;await LoadProductsAsync();await LoadPurchasesAsync();status.Text="Purchase saved and stock updated.";}catch(Exception e){MessageBox.Show(e.Message,"Purchase could not be saved",MessageBoxButton.OK,MessageBoxImage.Warning);}}
}